function createSchedule(events,random=Math.random){const pool=[...new Map(events.map(e=>[e.id,e])).values()];if(!pool.length)return [];const count=Math.min(pool.length,random()<.5?1:2),days=[2,3,4,5,6],out=[];for(let i=0;i<count;i++){const turn=days.splice(Math.floor(random()*days.length),1)[0],event=pool.splice(Math.floor(random()*pool.length),1)[0];out.push({turn,event})}return out.sort((a,b)=>a.turn-b.turn)}
function fresh(environment=null,random=Math.random){if(environment?.eventPool&&!environment.crises){environment=JSON.parse(JSON.stringify(environment));environment.crises=createSchedule(environment.eventPool,random);delete environment.eventPool;}return {environment,version:4,data:0,sent:0,budget:0,reportSent:false,rewarded:false,rescue:false,antenna:40,messageDay:0,panelHealth:100,day:1,energy:80,life:85,safety:90,food:75,science:0,water:70,parts:12,materials:70,morale:70,tasks:4,computer:3,efficiency:90,lifeMode:'normal',cabinC:22,thermalMode:'auto',insulation:false,irrigationUpgrade:false,lifeCap:100,leak:false,crop:null,light:'normal',labProgress:0,waterUpgrade:false,shelters:2,buildings:[],construction:null,engine:0,batteries:2,charge:0,auto:false,angle:40,over:false,won:false,log:[],used:[]}}
function phase(s){return s.realtime?(s.day-1)%7+1:s.day}
