function storm(s){if(Array.isArray(s.environment?.crises))return !!currentCrisis(s);if(s.environment&&Object.hasOwn(s.environment,'event')&&!s.environment.event)return false;return phase(s)===(s.environment?.stormTurn??5)}
function solarProfile(s){const c=currentCrisis(s)?.classType?.[0]||'X';return c==='C'?{health:90,transfer:10,exposure:8}:c==='M'?{health:80,transfer:8,exposure:16}:{health:65,transfer:5,exposure:24}}
