// One-way upper ellipse; wrap only after the entire Earth has crossed the edge.
function antennaPosition(s,elapsed){const phase=Math.PI-((Math.max(0,elapsed)+4)%28)/28*Math.PI,x=340+390*Math.cos(phase),y=300-235*Math.sin(phase);return {x,y,angle:Math.atan2(300-y,x-340)*180/Math.PI,cycle:Math.floor((Math.max(0,elapsed)+4)/28)}}
function antennaTarget(s,elapsed){return antennaPosition(s,elapsed).angle}
function protocolEnergy(s){return Math.ceil(8*(studyData(s)?.lightHours||16)/24)}
function thermalData(s){const d=s.environment?.science?.diviner;return d?.status==='online'?d.cells.find(c=>c.siteId===s.environment.site.id):null}
function studyData(s){const d=s.environment?.science?.osdr;return d?.status==='online'?d:null}
function thermal(s){const d=thermalData(s);if(!d)return null;const sun=Math.max(0,sky(s)?.sun.el||0),exteriorC=d.minK+(d.maxK-d.minK)*Math.pow(Math.sin(sun*Math.PI/180),.25)-273.15,mode=s.thermalMode||'auto',setpoint=mode==='eco'?16:s.light==='protocol'&&studyData(s)?studyData(s).temperatureC:22;const cost=mode==='off'?0:Math.max(1,Math.ceil(Math.abs(setpoint-exteriorC)/(exteriorC<setpoint?18:35)*(s.insulation ? .65 : 1)*(mode==='eco' ? .7 : 1)));return {exteriorC,setpoint,cost,mode,cabinC:s.cabinC??22}}

function night(s){return sky(s)?sky(s).sun.el<=0:phase(s)>=4}function optimum(s){return sky(s)?Math.round(Math.max(0,sky(s).sun.el)*100)/100:[0,40,80,125][phase(s)]||0}function capacity(s){return s.batteries*35}function storage(s){return s.buildings.includes('storage')?140:100}
function clamp(s){for(const[k,max]of Object.entries(LIMITS))s[k]=Math.max(0,Math.min(k==='food'||k==='water'?storage(s):k==='life'?s.lifeCap:k==='science'&&s.realtime?Number.MAX_SAFE_INTEGER:max,s[k]));s.charge=Math.max(0,Math.min(capacity(s),s.charge))}
