 for(const[k,c]of Object.entries(crops))add('plant_'+k,'Plant '+c.name,{water:6,tasks:1},`${c.duration}  days of normal growth → ${c.food?c.food+' food':c.science+' science'}. Water the crop and provide light for it to grow.`,!s.crop,'Harvest or discard the existing crop first');
