 if(id.startsWith('plant_')){s.crop={type:id.slice(6),progress:0,moisture:0,protocolTurns:0};if(s.light==='protocol')s.light='normal';}if(id==='water')s.crop.moisture=2;if(id==='discard')s.crop=null;if(id==='harvest'){const c=crops[s.crop.type];s.food+=c.food;s.science+=c.science;s.data+=c.science;if(s.crop.type==='experiment'&&s.crop.protocolTurns>=2){s.science+=10;s.data+=10;s.irrigationUpgrade=true;s.log.unshift('OSDR experiment complete. +10 science and data, and improved irrigation.');}s.crop=null}if(id.startsWith('light_'))s.light=id.slice(6);
