 if(s.leak&&!spend(6)){s.life-=6;notes.push('Pumps lost power. Oxygen drops by another 6.')}const heat=thermal(s);if(heat){const powered=heat.mode!=='off'&&spend(heat.cost);s.cabinC=powered?heat.setpoint:heat.cabinC+Math.sign(heat.exteriorC-heat.cabinC)*Math.min(8,Math.abs(heat.exteriorC-heat.cabinC));notes.push(`Thermal control. Estimated surface ${heat.exteriorC.toFixed(0)} °C,  cabin ${s.cabinC.toFixed(1)} °C; ${powered?heat.cost:0}  energy used${powered?'':'  (control off or unpowered)'}.`);if(s.cabinC<12||s.cabinC>30){s.safety-=12;s.morale-=6;notes.push('Thermal stress. Safety −12, morale −6. Crop growth paused.');}}else if(night(s)&&!spend(14)){s.safety-=12;notes.push('Heating lost power. Safety −12.')}const lifeEnergy=s.lifeMode==='normal'?8:3;const active=spend(lifeEnergy);const oxygen=active?Math.round((s.lifeMode==='normal'?18:10)*s.efficiency/100):0;s.life+=oxygen-14-(s.leak?14:0);notes.push(`Oxygen +${oxygen}  generated, −14 used by crew${s.leak?',  −14 from leak':''}.`);if(!active){s.safety-=10;notes.push('Life support lost power. Safety −10.')}s.efficiency=Math.max(15,s.efficiency-7);s.water-=4;s.food-=9;
 if(s.crop&&s.crop.progress<crops[s.crop.type].duration&&s.light!=='off'){const high=s.light==='high',protocol=s.light==='protocol'&&studyData(s),energy=protocol?protocolEnergy(s):high?9:4,comfortable=!thermalData(s)||(s.cabinC>=12&&s.cabinC<=30);if(comfortable&&(s.crop.moisture||0)>0&&spend(energy)){if(protocol&&Math.abs((s.cabinC??22)-protocol.temperatureC)<=3)s.crop.protocolTurns=(s.crop.protocolTurns||0)+1;s.crop.moisture--;s.crop.progress=Math.min(crops[s.crop.type].duration,s.crop.progress+(high?2:1));notes.push('Crop grew with water and energy.')}else notes.push('Growth paused. Check water, energy and temperature.');}
 s.morale+=s.buildings.includes('dorm')?8:-3;if(storm(s)){const protectedCrew=Math.min(4,s.shelters===3?4:3);s.safety-=(4-protectedCrew)*solarProfile(s).exposure+4;notes.push(`Solar alert: ${protectedCrew}/4 protegidos.`)}else s.safety-=2;
